# এসএসসি সাধারণ গণিত অধ্যায় ১২ (দুই চলকবিশিষ্ট সরল সহসমীকরণ) ও ১৩ (সসীম ধারা): প্রতি অনুশীলনী ৩০টি
from sqlib import *
import sympy as sp
x,y,n,k=sp.symbols('x y n k'); R=sp.Rational
def S2(e1,e2): r=sp.solve([e1,e2],[x,y],dict=True); return r
def one(e1,e2,ans): r=S2(e1,e2); assert len(r)==1 and r[0]=={x:ans[0],y:ans[1]},(r,ans)
def kind(e1,e2):
    r=sp.solve([e1,e2],[x,y],dict=True)
    if not r: return 'none'
    return 'inf' if len(r[0])<2 or any(v.free_symbols for v in r[0].values()) else 'one'
